--
-- Name: set_jobs_uuid(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_jobs_uuid() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN
        IF NEW.id IS NULL THEN
            NEW.id := gen_random_uuid();
        END IF;
        RETURN NEW;
    END;
    $$;


