    parent_id uuid,
    submission_type_id uuid,
    contract_no character varying(255),
    is_digital_signature boolean DEFAULT false NOT NULL,
    assigned_pic_id uuid,
    assigned_by_id uuid,
    received_at timestamp(0) without time zone,
    assigned_at timestamp(0) without time zone,
    finished_at timestamp(0) without time zone,
    closed_at timestamp(0) without time zone,
    closed_by uuid,
    origin_workflow_id uuid,
    contract_type_parent_id uuid,
    updated_by uuid,
    is_in_sub_workflow boolean DEFAULT false NOT NULL,
    branch_step_number integer,
    current_step_number integer,
    current_sub_workflow_id uuid,
    workflow_iteration integer DEFAULT 1 NOT NULL,
    sla_config_id uuid,
    sla_due_at timestamp(0) without time zone,
    current_stage_due_at timestamp(0) without time zone,
    sla_status character varying(30) DEFAULT 'on_track'::character varying NOT NULL,
    stage_sla_hours integer,
    sla_total_hours integer,
    stage_started_at timestamp(0) without time zone,
    overdue_notified_at timestamp(0) without time zone,
    origin_workflow_step_id uuid,
    contract_type_ancestry_id uuid
);


