--
-- Name: mv_dashboard_contracts; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_dashboard_contracts AS
 SELECT c.id,
    c.form_no,
    c.contract_no,
    c.title,
    c.status,
    c.created_by,
    c.initiated_by_id,
    c.assigned_pic_id,
    c.contract_type_id,
    c.submission_type_id,
    c.vendor_id,
    c.parent_id,
    c.contract_date,
    c.end_date,
    c.closed_at,
    c.closed_by,
    c.finished_at,
    c.created_at,
    c.updated_at,
    c.deleted_at,
    m.f2_price,
    init_u.company_id AS initiator_company_id,
    init_u.department_id AS initiator_department_id,
    creator_u.company_id AS creator_company_id,
    creator_u.department_id AS creator_department_id,
    init_c.region_id AS initiator_region_id,
    creator_c.region_id AS creator_region_id,
    init_c.company_group_id AS initiator_company_group_id,
    creator_c.company_group_id AS creator_company_group_id,
    creator_u.name AS creator_name,
    init_u.name AS initiator_name,
    ct.name AS contract_type_name,
    v.vendor_name,
    init_d.name AS initiator_department_name,
    creator_d.name AS creator_department_name
   FROM (((((((((public.t_contracts c
     LEFT JOIN public.t_contract_meta m ON ((c.id = m.contract_id)))
     LEFT JOIN public.m_users init_u ON ((c.initiated_by_id = init_u.id)))
     LEFT JOIN public.m_users creator_u ON ((c.created_by = creator_u.id)))
     LEFT JOIN public.m_companies init_c ON ((init_u.company_id = init_c.id)))
     LEFT JOIN public.m_companies creator_c ON ((creator_u.company_id = creator_c.id)))
     LEFT JOIN public.m_departments init_d ON ((init_u.department_id = init_d.id)))
     LEFT JOIN public.m_departments creator_d ON ((creator_u.department_id = creator_d.id)))
     LEFT JOIN public.m_contract_types ct ON ((c.contract_type_id = ct.id)))
     LEFT JOIN public.m_vendors v ON ((c.vendor_id = v.id)))
  WHERE (c.deleted_at IS NULL)
  WITH NO DATA;


